/**
 * @description An error encountered during SPF inspection
 * @type object
*/
export type EmailAuthInspectError = {
    /**
     * @description Error code. Known values:\n- `lookup_failed` — DNS TXT lookup failed\n- `spf_not_found` — no SPF record found\n- `invalid_spf` — record does not start with `v=spf1`\n- `invalid_domain` — PSL validation failed\n- `loop_detected` — include/redirect cycle detected\n- `invalid_mechanism` — unrecognised or malformed mechanism\n- `resource_limit_exceeded` — internal resource protection limits exceeded (recursion depth or query budget)\n- `max_lookups` — RFC 7208 10-lookup limit exceeded\n
     * @example max_lookups
     * @type string
    */
    code: string;
    /**
     * @description Additional error-specific details (optional).\n- For `invalid_domain` errors: the invalid domain string\n- For `invalid_mechanism` errors: the invalid mechanism text (e.g., \"invalidmech123\")\n- For `loop_detected` errors: the domain that caused the loop\n- For other error types: not present\n
     * @example invalid
     * @type string | undefined
    */
    details?: string | undefined;
    /**
     * @description Domain where the error occurred
     * @example example.com
     * @type string
    */
    domain: string;
    /**
     * @description Human-readable error message
     * @example RFC 7208 10-lookup limit exceeded
     * @type string
    */
    message: string;
};

/**
 * @description Recursive SPF inspection tree\n
 * @type object
*/
export type EmailAuthSpfTree = {
    /**
     * @description Parsed SPF components (mechanisms)
     * @type array
    */
    components: EmailAuthSpfComponent[];
    /**
     * @description Domain being inspected
     * @example example.com
     * @type string
    */
    domain: string;
    /**
     * @description All errors encountered during inspection, collected from the entire tree.\nThis includes errors from nested includes at any depth, providing a quick\noverview of all issues without needing to traverse the nested structure.\nEach error includes a `domain` field to identify where it occurred.\nEmpty array if no errors (omitted from JSON when empty).\n
     * @example []
     * @type array | undefined
    */
    errors?: EmailAuthInspectError[] | undefined;
    /**
     * @description Raw SPF record content
     * @example v=spf1 ip4:203.0.113.1 include:spf.example.com -all
     * @type string
    */
    record: string;
    /**
     * @description Total number of DNS lookups performed across all includes
     * @example 2
     * @type integer
    */
    total_lookups: number;
};

