export const emailAuthSpfComponentTypeEnum = {
    ALL: "ALL",
    A: "A",
    MX: "MX",
    IP4: "IP4",
    IP6: "IP6",
    EXISTS: "EXISTS",
    INCLUDE: "INCLUDE",
    PTR: "PTR",
    REDIRECT: "REDIRECT"
} as const;

export type EmailAuthSpfComponentTypeEnumKey = (typeof emailAuthSpfComponentTypeEnum)[keyof typeof emailAuthSpfComponentTypeEnum];

/**
 * @description A single SPF component (mechanism) in the inspection tree.\n\nThe `value` field includes the qualifier prefix (e.g., \"-all\", \"~mx:example.com\")\nto match the raw SPF record syntax. The qualifier is also available separately\nin the `result` field for programmatic access.\n
 * @type object
*/
export type EmailAuthSpfComponent = {
    /**
     * @description Number of DNS lookups this component requires (per RFC 7208).\n- MX, A, EXISTS, INCLUDE, REDIRECT, PTR: 1\n- IP4, IP6, ALL: 0\n
     * @example 0
     * @type integer
    */
    lookup_count: number;
    /**
     * @description Nested SPF tree for INCLUDE or REDIRECT mechanisms.\nOnly present for INCLUDE/REDIRECT components.\n
     * @type object | undefined
    */
    nested?: EmailAuthSpfTree | undefined;
    /**
     * @description SPF mechanism result qualifier
     * @type string
    */
    result: EmailAuthSpfResultKey;
    /**
     * @description Component type (UPPERCASE)
     * @example IP4
     * @type string
    */
    type: EmailAuthSpfComponentTypeEnumKey;
    /**
     * @description Component value with qualifier prefix.\nFor IP4/IP6, stores just the IP address (no \"ip4:\" or \"ip6:\" prefix).\nExamples: \"203.0.113.1\", \"203.0.113.0/24\", \"2001:db8::1/64\", \"-all\", \"~mx:example.com\", \"include:_spf.example.com\"\n
     * @example 203.0.113.1
     * @type string
    */
    value: string;
};

