/**
 * @description Create an allow policy.
*/
export type EmailSecurityCreateAllowPolicy = (EmailSecurityAllowPolicy & {
    /**
     * @description Bypasses all detections for messages to this recipient.
     * @example false
     * @type boolean
    */
    is_exempt_recipient: boolean;
} & {
    /**
     * @description Bypasses all detections and link following for messages from this sender.
     * @example true
     * @type boolean
    */
    is_trusted_sender: boolean;
} & {
    /**
     * @description Exempts messages from this sender from Spam, Spoof and Bulk dispositions only; Malicious and Suspicious dispositions still apply.
     * @example false
     * @type boolean
    */
    is_acceptable_sender: boolean;
} & {
    /**
     * @description The pattern value to match. The format depends on `pattern_type`: a valid email address for EMAIL (e.g. `user@example.com`), a valid domain name for DOMAIN (e.g. `example.com`), or a plain IPv4 address or IPv4 CIDR block for IP (e.g. `1.2.3.4` or `1.2.3.0/24`); the API accepts only globally reachable IP addresses and rejects private, loopback, link-local, and unspecified addresses.
     * @minLength 1
     * @maxLength 1024
     * @example test@example.com
     * @type string
    */
    pattern: string;
} & {
    /**
     * @example false
     * @type boolean
    */
    is_regex: boolean;
} & {
    /**
     * @description Enforce DMARC, SPF or DKIM authentication. When on, Email Security only honors policies that pass authentication.
     * @example true
     * @type boolean
    */
    verify_sender: boolean;
} & {
    /**
     * @description Type of pattern matching.\n- EMAIL: matches a full email address (e.g. `user@example.com`)\n- DOMAIN: matches a domain name (e.g. `example.com`)\n- IP: matches a plain IPv4 address (e.g. `1.2.3.4`) or an IPv4 CIDR block (e.g. `1.2.3.0/24`). The API accepts only globally reachable addresses.\n- UNKNOWN: deprecated; you cannot use this when creating or updating policies, but it may appear on existing entries.\n
     * @example EMAIL
     * @type string
    */
    pattern_type: EmailSecurityPatternTypeKey;
});

