/**
 * @description Category information for an asset.
 * @example {"id":"1a78cbf3-b98f-4289-b1f2-22db64130f4f","service":null,"type":"file","vendor":"Slack"}
 * @type object
*/
export type PostureApiAssetCategory = {
    /**
     * @description Unique identifier for the asset category.
     *
     * Format: `uuid`
     * @example 1a78cbf3-b98f-4289-b1f2-22db64130f4f
     * @type string | undefined
    */
    id?: string | undefined;
    /**
     * @description The specific service within the vendor the asset is part of (often none). Example - AWS is the vendor, S3 is the service.
     * @example OneDrive
     * @type string
    */
    service: string | null;
    /**
     * @description The type of asset.
     * @example file
     * @type string
    */
    type: string;
    /**
     * @description The vendor the asset is part of.
     * @example Slack
     * @type string
    */
    readonly vendor: string;
};

/**
 * @description Additional field information for an asset.
 * @example {"link":"https://example.com","name":"Credential name","value":"Test asset 2"}
 * @type object
*/
export type PostureApiAssetField = {
    /**
     * @description Optional link associated with the field.
     *
     * Format: `uri`
     * @example https://example.com
     * @type string | undefined
    */
    link?: (string | null) | undefined;
    /**
     * @description The name of the field.
     * @example File Name
     * @type string
    */
    name: string;
    /**
     * @description The value of the field.
     * @example sensitive-document.xlsx
     * @type string
    */
    value: string;
};

/**
 * @description Asset information including metadata and categorization.
 * @example {"external_id":"external-file-id-123","id":"8a043daf-def4-403e-9d28-da2e93d9b824","link":"https://slack-files.com/TYJH37DCK-E0238GG6B8-92fd5y5674","name":"Public.svg"}
 * @type object
*/
export type PostureApiAsset = {
    /**
     * @description Category information for an asset.
     * @example {"id":"1a78cbf3-b98f-4289-b1f2-22db64130f4f","service":null,"type":"file","vendor":"Slack"}
     * @type object
    */
    category: PostureApiAssetCategory;
    /**
     * @description External identifier from the source system.
     * @maxLength 512
     * @example external-file-id-123
     * @type string
    */
    external_id: string;
    /**
     * @description The fields associated with the asset.
     * @type array
    */
    readonly fields: PostureApiAssetField[];
    /**
     * @description Unique identifier for the asset.
     *
     * Format: `uuid`
     * @example 8a043daf-def4-403e-9d28-da2e93d9b824
     * @type string | undefined
    */
    id?: string | undefined;
    /**
     * @description Direct link to the asset.
     *
     * Format: `uri`
     * @maxLength 2048
     * @example https://slack-files.com/TYJH37DCK-E0238GG6B8-92fd5y5674
     * @type string | undefined
    */
    link?: (string | null) | undefined;
    /**
     * @description Human-readable name of the asset.
     * @example Public.svg
     * @type string
    */
    name: string;
};

