export type RealtimekitPreset = {
    config: {
        /**
         * @description Livestream viewer quality levels.
         * @default
         * @type array | undefined
        */
        livestream_viewer_qualities?: (number[] | null) | undefined;
        /**
         * @description Maximum number of screen shares that can be active at a given time
         * @type number
        */
        max_screenshare_count: number;
        /**
         * @description Maximum number of streams that are visible on a device
         * @type object
        */
        max_video_streams: {
            /**
             * @description Maximum number of video streams visible on desktop devices
             * @type number
            */
            desktop: number;
            /**
             * @description Maximum number of streams visible on mobile devices
             * @type number
            */
            mobile: number;
        };
        /**
         * @description Media configuration options. eg: Video quality
         * @type object
        */
        media: {
            /**
             * @description Control options for Audio quality.
             * @type object | undefined
            */
            audio?: {
                /**
                 * @description Enable High Quality Audio for your meetings
                 * @type boolean | undefined
                */
                enable_high_bitrate?: boolean | undefined;
                /**
                 * @description Enable Stereo for your meetings
                 * @type boolean | undefined
                */
                enable_stereo?: boolean | undefined;
            } | undefined;
            /**
             * @description Configuration options for participant screen shares
             * @type object
            */
            screenshare: {
                /**
                 * @description Frame rate of screen share
                 * @type number
                */
                frame_rate: number;
                /**
                 * @description Quality of screen share
                 * @type string
                */
                quality: RealtimekitPresetConfigMediaScreenshareQualityEnumKey;
            };
            /**
             * @description Configuration options for participant videos
             * @type object
            */
            video: {
                /**
                 * @description Frame rate of participants\' video
                 * @maxLength 30
                 * @type number
                */
                frame_rate: number;
                /**
                 * @description Video quality of participants
                 * @type string
                */
                quality: RealtimekitPresetConfigMediaVideoQualityEnumKey;
                /**
                 * @description Enable simulcast for participant videos.
                 * @default false
                 * @type boolean | undefined
                */
                simulcast?: boolean | undefined;
            };
        };
        /**
         * @description Type of the meeting
         * @type string
        */
        view_type: RealtimekitPresetConfigViewTypeEnumKey;
    };
    /**
     * @description Name of the preset
     * @type string
    */
    name: string;
    permissions: {
        accept_stage_requests?: boolean | undefined;
        /**
         * @description Whether this participant can accept waiting requests
         * @type boolean
        */
        accept_waiting_requests: boolean;
        can_accept_production_requests: boolean;
        can_change_participant_permissions: boolean;
        can_edit_display_name: boolean;
        can_livestream: boolean;
        can_record: boolean;
        can_spotlight: boolean;
        chat: {
            private: {
                can_receive: boolean;
                can_send: boolean;
                files: boolean;
                text: boolean;
            };
            public: {
                /**
                 * @description Can send messages in general
                 * @type boolean
                */
                can_send: boolean;
                /**
                 * @description Can send file messages
                 * @type boolean
                */
                files: boolean;
                /**
                 * @description Can send text messages
                 * @type boolean
                */
                text: boolean;
            };
        };
        connected_meetings: {
            can_alter_connected_meetings: boolean;
            can_switch_connected_meetings: boolean;
            can_switch_to_parent_meeting: boolean;
        };
        disable_participant_audio: boolean;
        disable_participant_screensharing: boolean;
        disable_participant_video: boolean;
        /**
         * @description Whether this participant is visible to others or not
         * @type boolean
        */
        hidden_participant: boolean;
        is_recorder?: boolean | undefined;
        kick_participant: boolean;
        /**
         * @description Media permissions
         * @type object
        */
        media: {
            /**
             * @description Audio permissions
             * @type object
            */
            audio: {
                /**
                 * @description Can produce audio
                 * @type string
                */
                can_produce: RealtimekitPresetPermissionsMediaAudioCanProduceEnumKey;
            };
            /**
             * @description Screenshare permissions
             * @type object
            */
            screenshare: {
                /**
                 * @description Can produce screen share video
                 * @type string
                */
                can_produce: RealtimekitPresetPermissionsMediaScreenshareCanProduceEnumKey;
            };
            /**
             * @description Video permissions
             * @type object
            */
            video: {
                /**
                 * @description Can produce video
                 * @type string
                */
                can_produce: RealtimekitPresetPermissionsMediaVideoCanProduceEnumKey;
            };
        };
        pin_participant: boolean;
        /**
         * @description Plugin permissions
         * @type object
        */
        plugins: {
            /**
             * @description Can close plugins that are already open
             * @type boolean
            */
            can_close: boolean;
            /**
             * @description Can edit plugin config
             * @type boolean
            */
            can_edit_config: boolean;
            /**
             * @description Can start plugins
             * @type boolean
            */
            can_start: boolean;
            /**
             * @description Plugin configuration keyed by plugin UUID.
             * @type object
            */
            config: RealtimekitPresetPluginConfig;
        };
        /**
         * @description Poll permissions
         * @type object
        */
        polls: {
            /**
             * @description Can create polls
             * @type boolean
            */
            can_create: boolean;
            /**
             * @description Can view polls
             * @type boolean
            */
            can_view: boolean;
            /**
             * @description Can vote on polls
             * @type boolean
            */
            can_vote: boolean;
        };
        /**
         * @description Type of the recording peer
         * @type string
        */
        recorder_type: RealtimekitPresetPermissionsRecorderTypeEnumKey;
        show_participant_list: boolean;
        stage_access?: RealtimekitPresetPermissionsStageAccessEnumKey | undefined;
        stage_enabled?: boolean | undefined;
        transcription_enabled?: boolean | undefined;
        /**
         * @description Waiting room type
         * @type string
        */
        waiting_room_type: RealtimekitPresetPermissionsWaitingRoomTypeEnumKey;
    };
    ui: {
        design_tokens: {
            border_radius: RealtimekitPresetUiDesignTokensBorderRadiusEnumKey;
            border_width: RealtimekitPresetUiDesignTokensBorderWidthEnumKey;
            colors: {
                background: {
                    "600": string;
                    "700": string;
                    "800": string;
                    "900": string;
                    "1000": string;
                };
                brand: {
                    "300": string;
                    "400": string;
                    "500": string;
                    "600": string;
                    "700": string;
                };
                danger: string;
                success: string;
                text: string;
                text_on_brand: string;
                video_bg: string;
                warning: string;
            };
            font_family?: string | undefined;
            google_font?: string | undefined;
            /**
             * @description
             * Format: `uri`
             * @type string | undefined
            */
            logo?: string | undefined;
            /**
             * @minLength 1
             * @type number
            */
            spacing_base: number;
            theme: RealtimekitPresetUiDesignTokensThemeEnumKey;
        };
    };
};

