export type WaitingroomEventResponseCollection = (WaitingroomApiResponseCollection & {
    result?: WaitingroomEventResult[] | undefined;
});

/**
 * @description The host name to which the waiting room will be applied (no wildcards). Please do not include the scheme (http:// or https://). The host and path combination must be unique.
 * @example shop.example.com
 * @type string
*/
export type WaitingroomHost = string;

/**
 * @description Identifier.
 * @maxLength 32
 * @example 023e105f4ecef8ad9ca31a8372d0c353
 * @type string
*/
export type WaitingroomIdentifier = string;

/**
 * @description Only available for the Waiting Room Advanced subscription. If `true`, requests to the waiting room with the header `Accept: application/json` will receive a JSON response object with information on the user\'s status in the waiting room as opposed to the configured static HTML page. This JSON response object has one property `cfWaitingRoom` which is an object containing the following fields:\n1. `inWaitingRoom`: Boolean indicating if the user is in the waiting room (always **true**).\n2. `waitTimeKnown`: Boolean indicating if the current estimated wait times are accurate. If **false**, they are not available.\n3. `waitTime`: Valid only when `waitTimeKnown` is **true**. Integer indicating the current estimated time in minutes the user will wait in the waiting room. When `queueingMethod` is **random**, this is set to `waitTime50Percentile`.\n4. `waitTime25Percentile`: Valid only when `queueingMethod` is **random** and `waitTimeKnown` is **true**. Integer indicating the current estimated maximum wait time for the 25% of users that gain entry the fastest (25th percentile).\n5. `waitTime50Percentile`: Valid only when `queueingMethod` is **random** and `waitTimeKnown` is **true**. Integer indicating the current estimated maximum wait time for the 50% of users that gain entry the fastest (50th percentile). In other words, half of the queued users are expected to let into the origin website before `waitTime50Percentile` and half are expected to be let in after it.\n6. `waitTime75Percentile`: Valid only when `queueingMethod` is **random** and `waitTimeKnown` is **true**. Integer indicating the current estimated maximum wait time for the 75% of users that gain entry the fastest (75th percentile).\n7. `waitTimeFormatted`: String displaying the `waitTime` formatted in English for users. If `waitTimeKnown` is **false**, `waitTimeFormatted` will display **unavailable**.\n8. `queueIsFull`: Boolean indicating if the waiting room\'s queue is currently full and not accepting new users at the moment.\n9. `queueAll`: Boolean indicating if all users will be queued in the waiting room and no one will be let into the origin website.\n10. `lastUpdated`: String displaying the timestamp as an ISO 8601 string of the user\'s last attempt to leave the waiting room and be let into the origin website. The user is able to make another attempt after `refreshIntervalSeconds` past this time. If the user makes a request too soon, it will be ignored and `lastUpdated` will not change.\n11. `refreshIntervalSeconds`: Integer indicating the number of seconds after `lastUpdated` until the user is able to make another attempt to leave the waiting room and be let into the origin website. When the `queueingMethod` is `reject`, there is no specified refresh time —\\_it will always be **zero**.\n12. `queueingMethod`: The queueing method currently used by the waiting room. It is either **fifo**, **random**, **passthrough**, or **reject**.\n13. `isFIFOQueue`: Boolean indicating if the waiting room uses a FIFO (First-In-First-Out) queue.\n14. `isRandomQueue`: Boolean indicating if the waiting room uses a Random queue where users gain access randomly.\n15. `isPassthroughQueue`: Boolean indicating if the waiting room uses a passthrough queue. Keep in mind that when passthrough is enabled, this JSON response will only exist when `queueAll` is **true** or `isEventPrequeueing` is **true** because in all other cases requests will go directly to the origin.\n16. `isRejectQueue`: Boolean indicating if the waiting room uses a reject queue.\n17. `isEventActive`: Boolean indicating if an event is currently occurring. Events are able to change a waiting room\'s behavior during a specified period of time. For additional information, look at the event properties `prequeue_start_time`, `event_start_time`, and `event_end_time` in the documentation for creating waiting room events. Events are considered active between these start and end times, as well as during the prequeueing period if it exists.\n18. `isEventPrequeueing`: Valid only when `isEventActive` is **true**. Boolean indicating if an event is currently prequeueing users before it starts.\n19. `timeUntilEventStart`: Valid only when `isEventPrequeueing` is **true**. Integer indicating the number of minutes until the event starts.\n20. `timeUntilEventStartFormatted`: String displaying the `timeUntilEventStart` formatted in English for users. If `isEventPrequeueing` is **false**, `timeUntilEventStartFormatted` will display **unavailable**.\n21. `timeUntilEventEnd`: Valid only when `isEventActive` is **true**. Integer indicating the number of minutes until the event ends.\n22. `timeUntilEventEndFormatted`: String displaying the `timeUntilEventEnd` formatted in English for users. If `isEventActive` is **false**, `timeUntilEventEndFormatted` will display **unavailable**.\n23. `shuffleAtEventStart`: Valid only when `isEventActive` is **true**. Boolean indicating if the users in the prequeue are shuffled randomly when the event starts.\n24. `turnstile`: Empty when turnstile isn\'t enabled. String displaying an html tag to display the Turnstile widget. Please add the `{{{turnstile}}}` tag to the `custom_html` template to ensure the Turnstile widget appears.\n25. `infiniteQueue`: Boolean indicating whether the response is for a user in the infinite queue.\n\nAn example cURL to a waiting room could be:\n\n	curl -X GET \"https://example.com/waitingroom\" \\\n		-H \"Accept: application/json\"\n\nIf `json_response_enabled` is **true** and the request hits the waiting room, an example JSON response when `queueingMethod` is **fifo** and no event is active could be:\n\n	{\n		\"cfWaitingRoom\": {\n			\"inWaitingRoom\": true,\n			\"waitTimeKnown\": true,\n			\"waitTime\": 10,\n			\"waitTime25Percentile\": 0,\n			\"waitTime50Percentile\": 0,\n			\"waitTime75Percentile\": 0,\n			\"waitTimeFormatted\": \"10 minutes\",\n			\"queueIsFull\": false,\n			\"queueAll\": false,\n			\"lastUpdated\": \"2020-08-03T23:46:00.000Z\",\n			\"refreshIntervalSeconds\": 20,\n			\"queueingMethod\": \"fifo\",\n			\"isFIFOQueue\": true,\n			\"isRandomQueue\": false,\n			\"isPassthroughQueue\": false,\n			\"isRejectQueue\": false,\n			\"isEventActive\": false,\n			\"isEventPrequeueing\": false,\n			\"timeUntilEventStart\": 0,\n			\"timeUntilEventStartFormatted\": \"unavailable\",\n			\"timeUntilEventEnd\": 0,\n			\"timeUntilEventEndFormatted\": \"unavailable\",\n			\"shuffleAtEventStart\": false\n		}\n	}\n\nIf `json_response_enabled` is **true** and the request hits the waiting room, an example JSON response when `queueingMethod` is **random** and an event is active could be:\n\n	{\n		\"cfWaitingRoom\": {\n			\"inWaitingRoom\": true,\n			\"waitTimeKnown\": true,\n			\"waitTime\": 10,\n			\"waitTime25Percentile\": 5,\n			\"waitTime50Percentile\": 10,\n			\"waitTime75Percentile\": 15,\n			\"waitTimeFormatted\": \"5 minutes to 15 minutes\",\n			\"queueIsFull\": false,\n			\"queueAll\": false,\n			\"lastUpdated\": \"2020-08-03T23:46:00.000Z\",\n			\"refreshIntervalSeconds\": 20,\n			\"queueingMethod\": \"random\",\n			\"isFIFOQueue\": false,\n			\"isRandomQueue\": true,\n			\"isPassthroughQueue\": false,\n			\"isRejectQueue\": false,\n			\"isEventActive\": true,\n			\"isEventPrequeueing\": false,\n			\"timeUntilEventStart\": 0,\n			\"timeUntilEventStartFormatted\": \"unavailable\",\n			\"timeUntilEventEnd\": 15,\n			\"timeUntilEventEndFormatted\": \"15 minutes\",\n			\"shuffleAtEventStart\": true\n		}\n	}
 * @default false
 * @example false
 * @type boolean
*/
export type WaitingroomJsonResponseEnabled = boolean;

export type WaitingroomMaxEstimatedTimeMinutes = number;

/**
 * @description A unique name to identify the waiting room. Only alphanumeric characters, hyphens and underscores are allowed.
 * @example production_webinar
 * @type string
*/
export type WaitingroomName = string;

/**
 * @description Sets the number of new users that will be let into the route every minute. This value is used as baseline for the number of users that are let in per minute. So it is possible that there is a little more or little less traffic coming to the route based on the traffic patterns at that time around the world.
 * @minLength 200
 * @maxLength 2147483647
 * @type integer
*/
export type WaitingroomNewUsersPerMinute = number;

/**
 * @description An ISO 8601 timestamp that marks when the next event will begin queueing.
 * @example 2021-09-28T15:00:00Z
 * @type string
*/
export type WaitingroomNextEventPrequeueStartTime = string | null;

/**
 * @description An ISO 8601 timestamp that marks when the next event will start.
 * @example 2021-09-28T15:00:00Z
 * @type string
*/
export type WaitingroomNextEventStartTime = string | null;

/**
 * @description Reorder the position of a rule
*/
export type WaitingroomRulePosition = ({
    /**
     * @description Places the rule in the exact position specified by the integer number <POSITION_NUMBER>. Position numbers start with 1. Existing rules in the ruleset from the specified position number onward are shifted one position (no rule is overwritten).
     * @type integer | undefined
    */
    index?: number | undefined;
} | {
    /**
     * @description Places the rule before rule <RULE_ID>. Use this argument with an empty rule ID value (\"\") to set the rule as the first rule in the ruleset.
     * @example <RULE_ID>
     * @type string | undefined
    */
    before?: string | undefined;
} | {
    /**
     * @description Places the rule after rule <RULE_ID>. Use this argument with an empty rule ID value (\"\") to set the rule as the last rule in the ruleset.
     * @example <RULE_ID>
     * @type string | undefined
    */
    after?: string | undefined;
});

export type WaitingroomPatchRule = {
    /**
     * @description The action to take when the expression matches.
     * @example bypass_waiting_room
     * @type string
    */
    action: WaitingroomRuleActionKey;
    /**
     * @description The description of the rule.
     * @default ''
     * @example allow all traffic from 10.20.30.40
     * @type string | undefined
    */
    description?: WaitingroomRuleDescription | undefined;
    /**
     * @description When set to true, the rule is enabled.
     * @default true
     * @example true
     * @type boolean | undefined
    */
    enabled?: WaitingroomRuleEnabled | undefined;
    /**
     * @description Criteria defining when there is a match for the current rule.
     * @example ip.src in {10.20.30.40}
     * @type string
    */
    expression: WaitingroomRuleExpression;
    /**
     * @description Reorder the position of a rule
    */
    position?: WaitingroomRulePosition | undefined;
};

/**
 * @description Sets the path within the host to enable the waiting room on. The waiting room will be enabled for all subpaths as well. If there are two waiting rooms on the same subpath, the waiting room for the most specific path will be chosen. Wildcards and query parameters are not supported.
 * @default '/'
 * @example /shop/checkout
 * @type string
*/
