    errors: {
        [key: string]: unknown;
    }[];
    messages: {
        [key: string]: unknown;
    }[];
    result: {
        edges: {
            /**
             * @description Deterministic composite edge id (source→target:relationshipType)
             * @type string
            */
            id: string;
            relationshipType: string;
            /**
             * @description Compact id of the source node (type:uuid)
             * @type string
            */
            source: string;
            sourceId: string;
            sourceType: string;
            /**
             * @description Compact id of the target node (type:uuid)
             * @type string
            */
            target: string;
            targetId: string;
            targetType: string;
        }[];
        /**
         * @description Focal node object (legacy single-seed). Null when unavailable.
         * @type object
        */
        node: {
            [key: string]: unknown;
        } | null;
        nodes: {
            [key: string]: unknown;
        }[];
    };
    result_info?: {
        /**
         * @description Number of nodes in result.nodes (seeds + neighbors)
         * @type number
        */
        count: number;
        /**
         * @description Opaque pagination cursor for the next page; null when exhausted or for multi-seed requests (single-seed only)
         * @type string | undefined
        */
        cursor?: (string | null) | undefined;
        /**
         * @description Traversal depth reached (always 1 for single-level)
         * @type number | undefined
        */
        depth_reached?: number | undefined;
        /**
         * @description Number of edges in result.edges
         * @type number
        */
        edge_count: number;
        /**
         * @description True when a cursor is available for the next page (single-seed only)
         * @type boolean | undefined
        */
        has_more?: boolean | undefined;
        /**
         * @description Total query time in milliseconds
         * @type number
        */
        query_time_ms: number;
        /**
         * @description Composite ids of the seed node(s) (type:uuid). Always an array, even for one seed.
         * @type array | undefined
        */
        seeds?: string[] | undefined;
        /**
         * @description Total count of nodes (same as count for this endpoint)
         * @type number
        */
        total_count: number;
        /**
         * @description True when results were capped (per-seed limit or max_nodes)
         * @type boolean | undefined
        */
        truncated?: boolean | undefined;
    } | undefined;
    success: boolean;
