export type GetResourceLibraryApplicationsQuery = {
    /**
     * @description Filter applications using key:value format. Supported filter keys:\n- name: Filter by application name (e.g., name:HR)\n- id: Filter by application ID (e.g., id:498)\n- human_id: Filter by human-readable ID (e.g., human_id:HR)\n- hostname: Filter by hostname or support domain (e.g., hostname:portal.example.com)\n- source: Filter by application source name (e.g., source:cloudflare)\n- ip_subnet: Filter by IP subnet using CIDR containment — returns applications where any stored subnet contains the search value (e.g., ip_subnet:10.0.1.5/32 matches apps with 10.0.0.0/16)\n- category_id: Filter by category ID (e.g., category_id:12).\n- category_name: Filter by category name (e.g., category_name:HR).\n- supported: Filter by supported Cloudflare product (e.g., supported:ACCESS). Values: GATEWAY, ACCESS, CASB.\n- review_status: Filter by the account\'s Gateway review status. Values: approved, unapproved, in_review, unreviewed.\n.\n
     * @type string | undefined
    */
    filter?: string | undefined;
    /**
     * @description Limit of number of results to return (max 250).
     * @default 25
     * @type integer | undefined
    */
    limit?: number | undefined;
    /**
     * @description Offset of results to return.
     * @default 0
     * @type integer | undefined
    */
    offset?: number | undefined;
    /**
     * @description Order results using field:direction format. Supported fields are name, id, human_id,\ncategory_id, application_type, application_confidence_score, and gen_ai_score.\nSupported directions are asc and desc. Ignored when search is provided; results are\nranked by relevance instead.\n
     * @type string | undefined
    */
    order_by?: string | undefined;
    /**
     * @description Fuzzy search across application name and hostnames. Results are ranked by relevance. Must be between 2 and 200 characters. Can be combined with filter parameters.
     * @minLength 2
     * @maxLength 200
     * @type string | undefined
    */
    search?: string | undefined;
    /**
     * @description Return only the listed properties on each application, as a comma-separated list.\nUse this to keep responses small when you only need part of each application — for\nexample populating a picker with `fields=id,name` instead of downloading every\nhostname and IP subnet.\n\nOmit this parameter to receive the full application object.\n\n`id` is always returned.\n\nSelectable properties: `id`, `name`, `human_id`, `version`, `hostnames`,\n`support_domains`, `ip_subnets`, `port_protocols`, `supported`, `gen_ai_score`,\n`application_confidence_score`, `created_at`, `updated_at`, `review_status`.\n\nUnknown or empty property names return `400`.\n
     * @type string | undefined
    */
    fields?: string | undefined;
};

